WITH RECURSIVE expected(i,a,b,c) AS (VALUES(0,1,2,3) UNION ALL SELECT i+1, ((a<<3)+b)&2147483647, ((b<<3)+c)&2147483647, ((c<<3)+a)&2147483647 FROM expected WHERE i<256) SELECT (SELECT count(*) FROM t1) AS actual_rows, (SELECT count(*) FROM (SELECT rowid,a,b,c FROM t1 EXCEPT SELECT i+1,a,b,c FROM expected)) AS unexpected_rows, (SELECT count(*) FROM (SELECT i+1,a,b,c FROM expected EXCEPT SELECT rowid,a,b,c FROM t1)) AS missing_rows;